from typing import List, Any, Dict, Tuple, Type

class Solution:

    """
    https://leetcode.com/problems/minimum-cost-path-with-teleportations/
    Difficulty: hard
    Solved: yes

    Idea:

    Start from upper-left and traverse cells to lower right, marking the cost to get to each cell. The cost
    can either be from a conventional move or from a teleport, whichever is cheapest.

    We do one pass through the grid for each number of teleports, starting from zero. On each pass, we update
    the cost map. We also update the teleport map, which maps cell value to the lowest cost of getting to
    some cell with that particular value. This is necessary because if, for example, we were teleport from
    one 5 cell to another 5 cell, we'd want to start from the 5 cell with the lowest cost of getting there.
    Of course, we can also start from any cell with a value HIGHER than 5, if the cost happens to be lower.

    On the next pass, the adjusted teleport map is used again in determining teleport costs.
    """

    GIANT_NUMBER = 1000000000
    MAX_DIGITS = 5

    debug = False

    def print_grid(self, grid: List[List[int]]):
        if not self.debug:
            return

        print("Grid:")
        print("-" * (len(grid[0]) * self.MAX_DIGITS))
        for row in grid:
            row_as_strs = [str(cell).rjust(self.MAX_DIGITS) for cell in row]
            row_as_strs = " ".join(row_as_strs)
            print(row_as_strs)
            print()

    def print_costs(self, costs: List[List[int]], teleports: int, teleported_here: int = -1):
        if not self.debug:
            return

        print(f"Costs, teleports = {teleports}:")
        print("---" * len(costs[0]))
        for row in costs:
            row_as_strs = ["*" * self.MAX_DIGITS if cell >= self.GIANT_NUMBER else str(cell).rjust(self.MAX_DIGITS) for cell in row]
            row_as_strs = " ".join(row_as_strs)
            print(row_as_strs)
            print()

    def minCost(self, grid: List[List[int]], k: int) -> int:

        grid_w = len(grid[0])
        grid_h = len(grid)

        vals_set = set()

        # Indexed by: y, x
        costs: List[List[int]] = []
        for row in grid:
            costs_row = [self.GIANT_NUMBER] * grid_w
            vals_set.update(row)
            costs.append(costs_row)
        costs[0][0] = 0

        # TODO: no value IDs
        # Let's just have the teleport map dictionary be keyed by raw values
        # As long as they're in order, we iterate through it until we get to key of certain size

        vals_list = sorted(vals_set, reverse=True)

        teleport_map: Dict[int, int] = {val : self.GIANT_NUMBER for val in vals_list}

        if self.debug:
            self.print_grid(grid)

        debug_change_count = 0

        # Note: in first pass, we redo grid so that it contains value indices rather than values

        for teleport in range(k + 1):

            for y in range(grid_h):
                for x in range(grid_w):
                    # Figure out the cost if we DON'T teleport here
                    # Example: if 1 teleport has been completed, we look at neighbors for which one teleport has been completed

                    val = grid[y][x]
                    if x > 0:
                        from_left_cost = costs[y][x-1]
                    else:
                        from_left_cost = self.GIANT_NUMBER
                    if y > 0:
                        from_above_cost = costs[y-1][x]
                    else:
                        from_above_cost = self.GIANT_NUMBER

                    if x == 0 and y == 0:
                        cost_no_t = 0
                    else:
                        cost_no_t = min(from_left_cost, from_above_cost)
                        cost_no_t += grid[y][x]

                    # Figure out the cost if we DO teleport here
                    if teleport >= 1:
                        cost_with_t = teleport_map[val]
                    else:
                        cost_with_t = self.GIANT_NUMBER

                    costs[y][x] = min(cost_with_t, cost_no_t)

            teleport_map_adjust: Dict[int, int] = {}
            for y in range(grid_h):
                for x in range(grid_w):
                    # Now we update the teleport map
                    val = grid[y][x]
                    cost_to_here = costs[y][x]

                    if cost_to_here < teleport_map[val]:
                        #self.print(f"**** adjusting cost for {val} to {cost_to_here} from {teleport_map[val]}")
                        teleport_map[val] = cost_to_here
                        teleport_map_adjust[val] = cost_to_here

            # Idea through example: if we have to adjust the cost for 6, it propagates down to every value below 6
            # However, if for a value below 6, we encounter a lower cost, we use that
            # Reminder: the keys in teleport_map are ordered large to small
            adjusted_cost = self.GIANT_NUMBER
            for map_val in teleport_map.keys():
                if teleport_map_adjust.get(map_val) is not None:
                    if teleport_map_adjust[map_val] < adjusted_cost:
                        adjusted_cost = teleport_map_adjust[map_val]
                if teleport_map[map_val] > adjusted_cost:
                    #self.print(f"**** cost for {map_val} becomes {adjusted_cost}, was {teleport_map[map_val]}")
                    teleport_map[map_val] = adjusted_cost

            if self.debug:
                self.print_costs(costs, teleport)

        #if self.debug:
        #    print(f"Teleport map: {teleport_map}")

        best_solution = self.GIANT_NUMBER
        if costs[grid_h-1][grid_w-1] < best_solution:
            best_solution = costs[grid_h-1][grid_w-1]

        return best_solution

    def print(self, val: Any):
        if self.debug:
            print(val)

Solution.debug = True
